code_string = """from qiskit import transpile

def run_and_analyze(circuit, aer_sim, graph):
    initial_params = [0.5] * circuit.num_parameters
    transpiled_circuit = transpile(circuit, aer_sim)

    def objective(params):
        parameter_binds = [{circuit.parameters[i]: [params[i]] for i in range(circuit.num_parameters)}]
        job = aer_sim.run(transpiled_circuit, parameter_binds=parameter_binds, shots=1024)
        result = job.result()
        counts = result.get_counts()
        expectation = compute_expectation(counts, graph)
        return -expectation

    from scipy.optimize import minimize
    opt_result = minimize(objective, initial_params, method='COBYLA')

    optimal_params = list(opt_result.x)
    parameter_binds = [{circuit.parameters[i]: [optimal_params[i]] for i in range(circuit.num_parameters)}]
    job = aer_sim.run(transpiled_circuit, parameter_binds=parameter_binds, shots=8192)
    result = job.result()
    counts = result.get_counts()

    sorted_counts = sorted(counts.items(), key=lambda x: x[1], reverse=True)
    top_two = [sorted_counts[0][0], sorted_counts[1][0]]

    return top_two"""

